select "c"."id", "c"."name", "c"."owner_id", "c"."current_book_id", "o"."handle" as "o_handle", "o"."name" as "o_name", "cb"."title" as "cb_title", "cb"."author" as "cb_author", (select coalesce(jsonb_agg(jsonb_build_array(t."v0", t."v1", t."v2")), jsonb_build_array()) from (select "pb"."id" as "v0", "pb"."title" as "v1", "pb"."author" as "v2" from "review" as "pv" join "book" as "pb" on "pb"."id" = "pv"."book_id" where "pv"."author_id" = "c"."owner_id" order by "pv"."created_at" desc, "pv"."id" desc fetch next ? rows only) as t) as "picks", (select count(*) from "membership" as "mc" where "mc"."club_id" = "c"."id") as "member_count", (select coalesce(jsonb_agg(jsonb_build_array(t."v0", t."v1", t."v2", t."v3")), jsonb_build_array()) from (select "r"."id" as "v0", "r"."handle" as "v1", "r"."name" as "v2", (select coalesce(jsonb_agg(jsonb_build_array(t."v0", t."v1", t."v2", t."v3", t."v4", t."v5", t."v6", t."v7")), jsonb_build_array()) from (select "v"."id" as "v0", "v"."rating" as "v1", "v"."body" as "v2", "v"."book_id" as "v3", "v"."author_id" as "v4", "v"."created_at" as "v5", "b"."title" as "v6", "b"."author" as "v7" from "review" as "v" join "book" as "b" on "b"."id" = "v"."book_id" where "v"."author_id" = "r"."id" order by "v"."created_at" desc, "v"."id" desc fetch next ? rows only) as t) as "v3" from "membership" as "m" join "reader" as "r" on "r"."id" = "m"."reader_id" where "m"."club_id" = "c"."id" order by "m"."joined_at", "r"."id" fetch next ? rows only) as t) as "members" from "club" as "c" left outer join "reader" as "o" on "o"."id" = "c"."owner_id" left outer join "book" as "cb" on "cb"."id" = "c"."current_book_id" order by "c"."id" fetch next ? rows only
